{"content":"package main

import (
	"fmt"
	"os"
	"strings"

	"example.com/ini/ini"
)

var failed = false

func check(f ini.File, sec, key, want string) {
	got, ok := f.Get(sec, key)
	status := "ok"
	if !ok || got != want {
		status = "FAIL"
		failed = true
	}
	fmt.Printf("%-4s %s.%s = %q (want %q)\n", status, sec, key, got, want)
}

func main() {
	doc := `
  ; indented comment
  # indented hash comment
  [  SERVER  ]
Host = X
host = y
url = http://x/?a=b ; note
a = 1 ; two # three
b = p ; q # r
c = "semi ; hash #"
d = "  pad  "
dup = 1
dup = 2
plain = x
`
	f, err := ini.Parse(strings.NewReader(doc))
	if err != nil {
		fmt.Println("unexpected error:", err)
		os.Exit(1)
	}
	check(f, "server", "host", "y")           // lower-cased section + key, overwrite
	check(f, "server", "url", "http://x/?a=b") // first '=' splits; value keeps '='
	check(f, "server", "a", "1")              // inline ';' comment (ws required)
	check(f, "server", "b", "p")              // inline ';' wins over '#'
	check(f, "server", "c", "semi ; hash #")  // quoted: content kept exactly, no inline comment
	check(f, "server", "d", "  pad  ")        // quoted: inner whitespace exact
	check(f, "server", "plain", "x")
	_, has := f.Get("server", "nope")
	fmt.Println("missing key ok:", !has)

	// semicolon without preceding whitespace is NOT a comment
	f2, err := ini.Parse(strings.NewReader("k = a;b\n"))
	if err != nil {
		fmt.Println("unexpected error:", err)
		os.Exit(1)
	}
	check(f2, "", "k", "a;b")

	// quoted value followed by inline comment
	f3, err := ini.Parse(strings.NewReader(`k = "v" ; tail\n`))
	if err != nil {
		fmt.Println("unexpected error:", err)
		os.Exit(1)
	}
	check(f3, "", "k", "v")

	// syntax error: 1-based line number
	_, err = ini.Parse(strings.NewReader("a = 1\njunk line\n"))
	fmt.Printf("syntax err: %v\n", err)
	if err == nil || !strings.Contains(err.Error(), "line 2") {
		failed = true
	}

	// no '=' but starts with '[' is not a section line -> syntax error
	_, err = ini.Parse(strings.NewReader("[oops\n"))
	fmt.Printf("bracket err: %v\n", err)
	if err == nil {
		failed = true
	}

	// empty section name
	f4, err := ini.Parse(strings.NewReader("k = v\n"))
	if err != nil {
		fmt.Println("unexpected error:", err)
		os.Exit(1)
	}
	check(f4, "", "k", "v")

	if failed {
		os.Exit(1)
	}
	fmt.Println("ALL OK")
}
